/**
 * EngravedPlate. The original ECHO owed tag as a
 * general plate: paper-coloured metal, text cut INTO it (dark accent with a
 * light top edge, the inverse of the emissive LCD readout), rivets at the
 * edges. Composes var(--echo-*); the accent-pressed-on-paper pairing is
 * contrast-checked in the theme tests so it survives a reseed.
 */
.echo-engraved-plate {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--echo-space-4) var(--echo-space-9);
  border-radius: var(--echo-radius-sm);
  transform: rotate(var(--echo-plate-tilt, 0deg));
  background: linear-gradient(
    180deg,
    var(--echo-paper-stock, var(--echo-text)) 0%,
    color-mix(in oklab, var(--echo-paper-stock, var(--echo-text)) 88%, var(--echo-cap-shadow)) 100%
  );
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / calc(0.7 * var(--echo-gloss, 1))),
    inset 0 -2px 3px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.18 * var(--echo-shade, 1) * 100%), transparent),
    0 6px 12px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.4 * var(--echo-shade, 1) * 100%), transparent);
}

.echo-engraved-plate__text {
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-widest, 0.25em);
  line-height: var(--echo-leading-none, 1);
  text-transform: uppercase;
  color: var(--echo-accent-pressed);
  /* The light edge below the stroke is what reads as CUT rather than printed. */
  text-shadow: 0 1px 0 rgb(255 255 255 / calc(0.6 * var(--echo-gloss, 1)));
}

.echo-engraved-plate__rivet {
  position: absolute;
  top: 50%;
  width: 6px;
  height: 6px;
  margin-top: -3px;
  border-radius: 50%;
  background: color-mix(in oklab, var(--echo-cast-ink, black) calc(0.13 * var(--echo-shade, 1) * 100%), transparent);
  box-shadow: inset 0 1px 1px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.4 * var(--echo-shade, 1) * 100%), transparent);
}

.echo-engraved-plate__rivet[data-side="start"] {
  inset-inline-start: 6px;
}

.echo-engraved-plate__rivet[data-side="end"] {
  inset-inline-end: 6px;
}

/* Rivets eat the padding they sit in, so a riveted plate is wider. */
.echo-engraved-plate:has(.echo-engraved-plate__rivet) {
  padding-inline: 26px;
}

/**
 * EngravedPlate — a debossed cream plate with rivets.
 * Generalized from the original ECHO `OwedTag`,
 * which hardcoded "Owed N": the value is the RENDERING — a machined plate
 * screwed onto the chassis — so the content is free-form and the domain noun
 * stays in the consumer.
 *
 * The one paper-coloured surface in the library. Use it for a fact that is
 * fixed to the device (a serial, a rating, a balance), not for a value that
 * updates while you watch — that is LcdChip's screen.
 */
import type { CSSProperties, HTMLAttributes, ReactNode } from "react";
import "./engraved-plate.css";

export interface EngravedPlateProps extends Omit<HTMLAttributes<HTMLSpanElement>, "children"> {
  /** The engraving. Short — a plate is stamped, not written on. */
  children: ReactNode;
  /** Rotation in degrees, as if screwed on slightly off-true. Default 0. */
  tilt?: number;
  /** Rivets at the plate's short edges. Default true. */
  rivets?: boolean;
}

export function EngravedPlate({
  children,
  tilt = 0,
  rivets = true,
  className,
  style,
  ...rest
}: EngravedPlateProps) {
  return (
    <span
      className={["echo-engraved-plate", className].filter(Boolean).join(" ")}
      // Tilt rides as a custom property (the sanctioned var-passthrough, as on
      // Loader's dot) so the transform stays in the stylesheet with the rest of
      // the material.
      style={{ "--echo-plate-tilt": `${tilt}deg`, ...style } as CSSProperties}
      {...rest}
    >
      {rivets ? (
        <>
          <span className="echo-engraved-plate__rivet" data-side="start" aria-hidden="true" />
          <span className="echo-engraved-plate__rivet" data-side="end" aria-hidden="true" />
        </>
      ) : null}
      <span className="echo-engraved-plate__text">{children}</span>
    </span>
  );
}
